using Test
using FinancialCalibrator
using FinancialMonteCarlo
using FinancialFFT
using FinancialToolbox
using Optim
using Dates

const FC = FinancialCalibrator

# Synthetic market: implied vols are generated by `true_model` priced with `method`.
function synthetic_market(true_model, method; S0 = 100.0, r = 0.01, d = 0.0, T = [0.5, 1.0, 2.0], strikes = collect(80.0:10.0:120.0))
    p = FinancialMonteCarlo.get_parameters(true_model)
    vols = reduce(vcat, [blsimpv.(S0, strikes, r, t, FC.smile_prices(true_model, method, p, strikes, r, t), d)' for t in T])
    dates = [Date(2020, 1, 1) + Day(round(Int, 365 * t)) for t in T]
    return MarketData(S0, T, dates, fill(r, length(T)), fill(d, length(T)), strikes, vols)
end

@testset "Models and methods" begin
    mkt = adapter(retriever(CalibrationID("Dax", "22Aug2016", "EUR"), IOFileInputStrategy()))
    curve = FinancialMonteCarlo.ImpliedCurve(mkt.ImpliedDividend, mkt.TimeToMaturity)
    und = FinancialMonteCarlo.Underlying(mkt.S0, curve)
    idx = 3
    prices(model, method) = FC.smile_prices(model, method, FinancialMonteCarlo.get_parameters(model), mkt.Strikes, mkt.ZeroRates[idx], mkt.TimeToMaturity[idx])

    levy_models = ("BlackScholes" => BlackScholesProcess(0.2, und), "Merton" => MertonProcess(0.2, 0.5, -0.1, 0.2, und), "Kou" => KouProcess(0.2, 0.5, 0.4, 10.0, 15.0, und), "VarianceGamma" => VarianceGammaProcess(0.2, -0.03, 0.16, und), "NIG" => NormalInverseGaussianProcess(0.2, -0.03, 0.16, und))
    methods = ("CarrMadan" => CarrMadanMethod(400.0, 14), "CarrMadanLewis" => CarrMadanLewisMethod(400.0, 14), "Lewis" => LewisMethod(100.0, 4001), "Cos" => CosMethod(1024))

    @testset "$mname" for (mname, model) in levy_models
        ref = prices(model, last(methods[2]))
        @test all(isfinite, ref)
        @test all(>(0), ref)
        @testset "$ename" for (ename, method) in methods
            pr = prices(model, method)
            @test length(pr) == length(mkt.Strikes)
            @test all(isfinite, pr)
            @test isapprox(pr, ref; rtol = 1e-3, atol = 0.05)
            loss = FC.Loss(FinancialMonteCarlo.get_parameters(model), model, method, mkt)
            @test loss < 1e4
        end
    end

    @testset "Heston" begin
        model = HestonProcess(0.3, 0.04, 1.0, 0.04, -0.5, 0.04, und)
        pr_cm = prices(model, CarrMadanMethod(400.0, 14))
        pr_cml = prices(model, CarrMadanLewisMethod(400.0, 14))
        @test all(isfinite, pr_cm)
        @test isapprox(pr_cm, pr_cml; rtol = 1e-3, atol = 0.05)
        @test FC.Loss(FinancialMonteCarlo.get_parameters(model), model, CarrMadanMethod(400.0, 14), mkt) < 1e4
    end

    @testset "Calibration recovers a synthetic surface" begin
        und0 = FinancialMonteCarlo.Underlying(100.0)
        cm = CarrMadanMethod(400.0, 14)

        @testset "BlackScholes / $name" for (name, method) in ("CarrMadan" => cm, "Cos" => CosMethod(1024), "Lewis" => LewisMethod(100.0, 4001))
            smkt = synthetic_market(BlackScholesProcess(0.2, und0), method)
            start = BlackScholesProcess(0.35, und0)
            res = calibrate(start, method, smkt)
            @test res.OptimalValue < 1e-3
            @test res.OptimalParam[1] ≈ 0.2 atol = 1e-2
            @test size(res.ModelVolatility) == size(smkt.Volatility)
            @test isapprox(res.ModelVolatility, smkt.Volatility; atol = 5e-3)
        end

        @testset "VarianceGamma / CarrMadan" begin
            smkt = synthetic_market(VarianceGammaProcess(0.2, -0.1, 0.2, und0), cm)
            start = VarianceGammaProcess(0.25, -0.05, 0.3, und0)
            loss0 = FC.Loss(FinancialMonteCarlo.get_parameters(start), start, cm, smkt)
            res = calibrate(start, cm, smkt)
            @test res.OptimalValue < loss0 / 10
        end

        @testset "Optimizer options" begin
            smkt = synthetic_market(VarianceGammaProcess(0.2, -0.1, 0.2, und0), cm)
            start = VarianceGammaProcess(0.25, -0.05, 0.3, und0)
            loss0 = FC.Loss(FinancialMonteCarlo.get_parameters(start), start, cm, smkt)
            short = calibrate(start, cm, smkt, NelderMead(), Optim.Options(iterations = 2))
            full = calibrate(start, cm, smkt, NelderMead(), Optim.Options(iterations = 100))
            @test short.OptimalValue <= loss0
            @test full.OptimalValue < short.OptimalValue
        end

        @testset "ShiftedLogNormalMixture / Analytic" begin
            true_model = ShiftedLogNormalMixture([0.15, 0.3], [0.5], -0.1, und0)
            smkt = synthetic_market(true_model, AnalyticMethod())
            start = ShiftedLogNormalMixture([0.2, 0.25], [0.4], -0.05, und0)
            loss0 = FC.Loss(FinancialMonteCarlo.get_parameters(start), start, AnalyticMethod(), smkt)
            res = calibrate(start, AnalyticMethod(), smkt)
            @test res.OptimalValue < loss0 / 10
        end
    end
end
